static int parseInt(Parser *p) { skip(p); int sign=1, v=0; if(p->s[p->pos]=='-'){sign=-1;p->pos++;} while(p->pos<p->len && p->s[p->pos]>='0'&&p->s[p->pos]<='9'){v=v*10+(p->s[p->pos]-'0');p->pos++;} return sign*v; }
static void expect(Parser *p, char ch){ skip(p); if(p->pos<p->len && p->s[p->pos]==ch) p->pos++; }
static int** parse2D(const char *s, int *rows) {
    Parser p={s,0,(int)strlen(s)}; int cap=16,n=0; int **a=(int**)malloc(cap*sizeof(int*));
    expect(&p,'['); skip(&p); if(p.pos<p.len && p.s[p.pos]==']'){p.pos++;*rows=0;return a;}
    while(p.pos<p.len){
        expect(&p,'['); int *v=(int*)malloc(2*sizeof(int)); v[0]=parseInt(&p); expect(&p,','); v[1]=parseInt(&p); expect(&p,']');
