class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[1]));
        int removals = 0;
        int prevEnd = Integer.MIN_VALUE;
        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];
            if (start < prevEnd) removals++;
            else prevEnd = end;
        }
        return removals;
    }
}

