    static List<String> splitTopLevel(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        parts.add(s.substring(start).trim());
        return parts;
    }
    static int[][] parse2D(String s) {
        s = s.trim();
        String inner = s.substring(1, s.length() - 1);
        if (inner.trim().isEmpty()) return new int[0][2];
        List<String> rows = splitTopLevel(inner);
        int[][] out = new int[rows.size()][2];
        for (int i = 0; i < rows.size(); i++) {
            String row = rows.get(i).trim();
            String body = row.substring(1, row.length() - 1);
            String[] nums = body.split(",");
            out[i][0] = Integer.parseInt(nums[0].trim());
            out[i][1] = Integer.parseInt(nums[1].trim());
        }
        return out;
    }
    static String nextTopLevel(String line) {
        String s = line.trim().substring(1, line.trim().length() - 1).trim();
        int depth = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) return s.substring(0, i).trim();
        }
        return s;
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[][] intervals = parse2D(nextTopLevel(line));
        System.out.println(new Solution().eraseOverlapIntervals(intervals));
    }
}

